#include <future>
#include <iostream>
#include <stdexcept>

int main() {
  auto f = std::async(std::launch::async, []() -> int {
    throw std::runtime_error("boom");
  });
  try {
    std::cout << f.get() << '\n';
  } catch (const std::runtime_error& e) {
    std::cout << "caught " << e.what() << '\n';
  }
}

