#include <future>
#include <iostream>

int main() {
  std::packaged_task<int()> task([] { return 7; });
  auto f = task.get_future();
  task();
  try {
    task();
  } catch (const std::future_error& e) {
    std::cout << (e.code() == std::future_errc::promise_already_satisfied);
  }
  std::cout << f.get() << '\n';
}

